#include "tigersheets/session.hpp"
#include "tigersheets/financial_models.hpp"
#include "tigersheets/pivot.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{WorkbookSession session({{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Model"},{"cells",Json::array({{{"row",1},{"col",1},{"input","Region"}},{{"row",1},{"col",2},{"input","Revenue"}},{{"row",2},{"col",1},{"input","East"}},{{"row",2},{"col",2},{"input","10"}}})}}})}});CalculationContext context;context.snapshot=session.snapshot();const Json forecast={{"version",1},{"id","f"},{"name","Forecast"},{"kind","forecast"},{"periods",2},{"drivers",Json::array({{{"name","Revenue"},{"base",100},{"growth",0.1}}})},{"output",{{"sheet","s"},{"row1",5},{"col1",1}}}};std::string error;const auto report=generateFinancialModel(context.snapshot,forecast,context);const bool made=session.apply(0,financialModelOperations(context.snapshot,report),&error);require(made,error.c_str());const Json reserved={{"version",1},{"id","future-input"},{"name","Future input"},{"kind","assumption_set"},{"cells",Json::array({{{"sheet","s"},{"row",10},{"col",1},{"type","blank"},{"value",nullptr}}})}};require(session.apply(session.snapshotView().at("revision"),saveFinancialDefinitionOperations(session.snapshotView(),reserved),&error),"reserve an empty future financial input");const auto before=session.snapshot();const Json pivot={{"id","p"},{"name","RegionRevenue"},{"source",{{"sheet","s"},{"row1",1},{"col1",1},{"row2",2},{"col2",2}}},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"}}})},{"output",{{"sheet","s"},{"row1",10},{"col1",1}}}};CalculationEngine engine;const auto generated=generatePivot(before,engine.calculate(before),pivot);require(!session.apply(before.at("revision"),pivotOperations(before,generated),&error)&&session.snapshotView()==before,"native PivotTable publication must refuse collisions with saved blank financial inputs atomically");std::cout<<"financial pivot collision tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
